# Check if x+y covers all residues modulo K_test for x, y in {0, ..., N-1}
max_sum = 2 * (N - 1)
if max_sum >= K_test - 1:
    # Since max_sum = 2(N-1) = K_test - 1, all residues are covered.
    print(f"Max sum {max_sum} is >= K_test - 1 ({K_test - 1}). All K_test residues are covered.")
else:
    print("Warning: Not all residues are covered.")

N = 2
K = N**3 # K=8
colors = list(range(1, K + 1))

# Define coloring function: all cubes unique
# C[i][j][k] = color of cube (i+1, j+1, k+1)
C = {}
for i in range(N):
    for j in range(N):
        for k in range(N):
            C[(i, j, k)] = (i * N*N) + (j * N) + k + 1

# Function to get set of colors in a slice (e.g., z=z0)
def get_slice_colors(slices_type, index, N, C):
    colors = set()
    if slices_type == 'xy': # Fixed z=index
        for i in range(N):
            for j in range(N):
                colors.add(C[(i, j, index)])
    elif slices_type == 'xz': # Fixed y=index
        for i in range(N):
            for k in range(N):
                colors.add(C[(i, index, k)])
    elif slices_type == 'yz': # Fixed x=index
        for j in range(N):
            for k in range(N):
                colors.add(C[(index, j, k)])
    return frozenset(colors)

# Calculate color sets for all slices
S_xy = set()
for z in range(N):
    S_xy.add(get_slice_colors('xy', z, N, C))

S_xz = set()
for y in range(N):
    S_xz.add(get_slice_colors('xz', y, N, C))

S_yz = set()
for x in range(N):
    S_yz.add(get_slice_colors('yz', x, N, C))

# Check the condition: S_xy must be a subset of S_xz intersect S_yz
intersection = S_xz.intersection(S_yz)
subset_check = S_xy.issubset(intersection)

print(f"S_xy: {S_xy}")
print(f"S_xz: {S_xz}")
print(f"S_yz: {S_yz}")
print(f"Is S_xy subset of (S_xz intersection S_yz)? {subset_check}")

